/* CAN intrusion detector: rules + int8 MLP, one call per received frame.
 *
 * Portable C (no HAL): the same file is compiled for the STM32 and for the PC
 * (ml/src/check_c_detector.py compares it frame by frame with the Python pipeline).
 * Tables and weights come from ids_model.h, generated by ml/src/export_c.py.
 */
#ifndef IDS_DETECTOR_H
#define IDS_DETECTOR_H

#include <stdint.h>

#define IDS_FEATURES 27

typedef struct {
    uint32_t t_us;      /* receive time in microseconds (wraps after 71 min, handled) */
    uint16_t can_id;    /* 11-bit ID (ROAD also uses 0xFFF) */
    uint8_t  dlc;       /* missing bytes are treated as 0 */
    uint8_t  data[8];
} ids_frame_t;

/* Severity, as on the dashboard */
enum { IDS_NORMAL = 0, IDS_WARNING = 1, IDS_ALERT = 2 };

/* Why this frame is suspicious (before smoothing), bit flags */
#define IDS_R_UNKNOWN_ID  0x01u  /* ID not in the whitelist: ALERT at once */
#define IDS_R_TOO_FAST    0x02u  /* rate rule */
#define IDS_R_MODEL       0x04u  /* MLP probability >= threshold */
#define IDS_R_STRONG      0x08u  /* impossible value or broken signal pair */

typedef struct {
    uint8_t level;          /* IDS_NORMAL / IDS_WARNING / IDS_ALERT, after k-of-n smoothing */
    uint8_t reasons;        /* IDS_R_* flags of this frame */
    uint8_t novel_bytes;    /* bit j: byte j has a value never seen / out of range for this ID */
    uint8_t pair_bytes;     /* bit j: byte j contradicts its partner signal (> 8 bits) */
    int8_t  score_q;        /* model output, int8; probability = (score_q + 128) / 256; -128 if not run */
    int8_t  features_q[IDS_FEATURES];  /* quantized model input (for verification) */
} ids_result_t;

void  ids_reset(void);                                  /* forget all per-ID history */
void  ids_process(const ids_frame_t *f, ids_result_t *r);
int8_t ids_model_run(const int8_t *features_q);   /* int8 MLP only: 27 inputs -> int8 output */
float ids_probability(int8_t score_q);
const char *ids_level_name(uint8_t level);

#endif
